using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Web.Script.Serialization;
class Attributes43 {
 static void Main(string[] a){var h=Assembly.LoadFrom(Path.Combine(a[0],"BESHStatNG.dll"));var rows=new List<object>();foreach(var t in h.GetTypes())foreach(var m in t.GetMethods(BindingFlags.Public|BindingFlags.Static)){var attr=m.GetCustomAttributes(false).FirstOrDefault(x=>x.GetType().Name=="ExcelFunctionAttribute");if(attr==null)continue;var values=new Dictionary<string,object>();foreach(string n in new[]{"Name","IsVolatile","IsThreadSafe","IsMacroType","IsExceptionSafe","ExplicitRegistration","IsHidden"}){var f=attr.GetType().GetField(n);var p=attr.GetType().GetProperty(n);values[n]=f!=null?f.GetValue(attr):p!=null?p.GetValue(attr,null):null;}rows.Add(new{method=t.FullName+"."+m.Name,flags=values});}File.WriteAllText(a[1],new JavaScriptSerializer{MaxJsonLength=int.MaxValue}.Serialize(new{exports=rows}));Console.WriteLine("Actual constructed Excel-DNA registration flags "+rows.Count);}
}
